Proof. intros (_ & B & _ & _ & _) Ha. left. lia. Qed.
Lemma cwr_block LB B n a : In (B, n) LB -> B <= a < B + n -> cwr LB a.
Proof. intros Hin Ha. right. left. exists (B, n). split; [exact Hin| cbn; lia]. Qed.

