Lemma iss_unread_where M ois str sm :
  PM.iss_at segs A T3 M ois str sm ->
  (ois + 81 <= PM.sm_g sm /\ PM.sm_eg sm <= ois + 104)
  \/ (exists c n p, str = PM.VLong c n p /\ p <= PM.sm_g sm /\ PM.sm_eg sm <= p + c).
