  PM.sr_qc (PM.p_src s) <= de' -> 0 <= rem' -> de' + rem' <= PM.sr_qc (PM.p_src s) + PM.CHUNK ->
  PM.parser_at segs A T3 T4 M' op ois (PMPS.with_src s (PM.SRC (PM.sr_qc (PM.p_src s)) de' rem')).
