Lemma parser_at_keep op ois s :
  PM.parser_at segs A T3 T4 M op ois s -> 0 <= op -> op + 384 <= 2 ^ 64 -> ag op 384 ->
  dkr M M' (PM.sr_qc (PM.p_src s)) PM.CHUNK ->
  0 <= PM.p_b s -> PM.p_b s + 32 * 2 ^ PM.p_k s <= 2 ^ 64 -> ag (PM.p_b s) (32 * 2 ^ PM.p_k s) ->
